@layer moduix.components {
  .root {
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-card);
    color: var(--moduix-color-card-foreground);
    box-shadow: var(--moduix-shadow-sm);
  }

  .panel {
    box-sizing: border-box;
    padding: var(--moduix-spacing-4);

    &[data-dragging] {
      user-select: none;
    }
  }

  .resizeTrigger {
    position: relative;
    z-index: 1;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 1px;
    padding: 0;
    border: 0;
    background: transparent;
    appearance: none;
    outline: 0;

    &::before {
      position: absolute;
      width: 0.5px;
      height: 100%;
      background-color: var(
        --moduix-splitter-resize-trigger-line-color,
        var(--moduix-color-border)
      );
      content: '';
      transition: background-color var(--moduix-transition-default);
    }

    &::after {
      position: absolute;
      width: var(--moduix-splitter-resize-trigger-size, var(--moduix-spacing-2-5));
      height: 100%;
      content: '';
    }

    &[data-orientation='vertical'] {
      width: 100%;
      height: 1px;

      &::before {
        width: 100%;
        height: 0.5px;
      }

      &::after {
        width: 100%;
        height: var(--moduix-splitter-resize-trigger-size, var(--moduix-spacing-2-5));
      }
    }

    &[data-dragging]::before {
      background-color: color-mix(in oklab, var(--moduix-color-muted-foreground) 40%, transparent);
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }

    &:focus-visible:not([data-dragging]):not(:has(.resizeTriggerIndicator))::after {
      outline: var(--moduix-focus-ring-width, var(--moduix-border-width-md)) solid
        var(--moduix-color-ring);
      outline-offset: var(--moduix-border-width-sm);
    }
  }

  .resizeTriggerIndicator {
    position: absolute;
    box-sizing: border-box;
    width: var(--moduix-spacing-1-5);
    height: var(--moduix-size-xs);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-color-background);
    box-shadow: var(--moduix-shadow-sm);
    pointer-events: none;
    transition:
      border-color var(--moduix-transition-default),
      box-shadow var(--moduix-transition-default),
      transform var(--moduix-transition-default);

    &[data-orientation='vertical'] {
      width: var(--moduix-size-xs);
      height: var(--moduix-spacing-1-5);
    }

    &[data-dragging] {
      box-shadow: var(--moduix-shadow-md);
      transform: scale(1.08);
    }

    &[data-disabled] {
      visibility: hidden;
    }
  }

  .resizeTrigger:focus-visible:not([data-dragging]) .resizeTriggerIndicator {
    outline: var(--moduix-focus-ring-width, var(--moduix-border-width-md)) solid
      var(--moduix-color-ring);
    outline-offset: var(--moduix-border-width-sm);
  }

  @media (hover: hover) {
    .resizeTrigger:hover::before {
      background-color: color-mix(in oklab, var(--moduix-color-muted-foreground) 40%, transparent);
    }

    .resizeTrigger:hover .resizeTriggerIndicator {
      border-color: color-mix(in oklab, var(--moduix-color-muted-foreground) 40%, transparent);
      box-shadow: var(--moduix-shadow-md);
    }
  }
}

import {
  SplitterContext,
  createSplitterRegistry,
  useSplitter,
  useSplitterContext,
} from '@ark-ui/vue/splitter';
import Splitter from './Splitter.vue';
import SplitterPanel from './SplitterPanel.vue';
import SplitterResizeTrigger from './SplitterResizeTrigger.vue';
import SplitterResizeTriggerIndicator from './SplitterResizeTriggerIndicator.vue';
import SplitterRootProvider from './SplitterRootProvider.vue';

export {
  createSplitterRegistry,
  Splitter,
  SplitterContext,
  SplitterPanel,
  SplitterResizeTrigger,
  SplitterResizeTriggerIndicator,
  SplitterRootProvider,
  useSplitter,
  useSplitterContext,
};

export type {
  SplitterContextProps,
  SplitterExpandCollapseDetails,
  SplitterPanelData,
  SplitterPanelProps,
  SplitterResizeDetails,
  SplitterResizeEndDetails,
  SplitterResizeTriggerIndicatorProps,
  SplitterResizeTriggerProps,
  SplitterRootEmits,
  SplitterRootProps,
  SplitterRootProviderProps,
  UseSplitterContext,
  UseSplitterProps,
  UseSplitterReturn,
} from '@ark-ui/vue/splitter';
